function cvss31(vec){try{const T={AV:{N:0.85,A:0.62,L:0.55,P:0.2},AC:{L:0.77,H:0.44},UI:{N:0.85,R:0.62},C:{H:0.56,L:0.22,N:0},I:{H:0.56,L:0.22,N:0},A:{H:0.56,L:0.22,N:0}};const p={};String(vec).split("/").forEach(kv=>{const i=kv.indexOf(":");if(i>0)p[kv.slice(0,i)]=kv.slice(i+1);});if(!(p.AV in T.AV)||!(p.AC in T.AC)||!(p.UI in T.UI)||!(p.S==="U"||p.S==="C")||!(p.C in T.C)||!(p.I in T.I)||!(p.A in T.A))return null;if(!(p.PR==="N"||p.PR==="L"||p.PR==="H"))return null;const PR=p.PR==="N"?0.85:p.PR==="L"?(p.S==="C"?0.68:0.62):(p.S==="C"?0.5:0.27);const iss=1-(1-T.C[p.C])*(1-T.I[p.I])*(1-T.A[p.A]);const issC=Math.max(iss-0.029,0);const imp=p.S==="U"?6.42*iss:7.52*issC-3.25*Math.pow(issC,15);if(imp<=0)return 0;const exp=8.22*T.AV[p.AV]*T.AC[p.AC]*PR*T.UI[p.UI];const s=p.S==="U"?Math.min(imp+exp,10):Math.min(1.08*(imp+exp),10);return Math.ceil(s*10-1e-9)/10;}catch(e){return null;}}
