files.forEach(f=>{const lines=f.content.split("\n");lines.forEach((ln,i)=>{if(sel.has("secrets"))SECRET_RES.forEach(([re,label,sev])=>{const m=ln.match(re);if(m){const col=ln.indexOf(m[0])+1;const masked=ln.replace(m[0],m[0].slice(0,4)+maskSecret(m[0].slice(4)));findings.push(mkFinding({title:label+" — secret exposé",severity:sev,category:"A07 Auth Failures",location:`${f.name} — Line ${i+1}, Col ${col}`,file:f.name,line:i+1,col,func:guessFunc(lines,i),evidence:`${f.name}:${i+1}: ${masked.trim().slice(0,160)}`,code:ln.trim().slice(0,220),cvss:sev==="CRITICAL"?9.0:7.5,dedup:"secret:"+label,problem:"Clé intégrée au code, récupérable via dépôt ou bundle distribué.",recommendation:"Variable d'environnement ou gestionnaire de secrets, jamais dans le code.",fix:`process.env.${label.replace(/\W+/g,"_").toUpperCase().slice(0,24)}`,verify:"Nouveau scan → RESOLVED"}));}});if(sel.has("source")||sel.has("api")||sel.has("auth"))SAST_RES.forEach(([re,label,sev,cat])=>{if(re.test(ln))findings.push(mkFinding({title:label,severity:sev,category:cat,location:`${f.name} — Line ${i+1}`,file:f.name,line:i+1,col:ln.search(re)+1,func:guessFunc(lines,i),evidence:ln.trim().slice(0,200),code:ln.trim().slice(0,220),cvss:sev==="HIGH"?7.5:sev==="MEDIUM"?5.0:3.0,dedup:"sast:"+label,problem:label+".",recommendation:"Assainir / API sûre / revue.",fix:"Voir recommandation OWASP "+cat,verify:"Re-scan SAST"}));});});});
