async function loadGitHub(url,branch){const m=url.match(/github\.com\/([^\/]+\/[^\/#\?]+)/i);if(!m)throw new Error("URL GitHub invalide");const repo=m[1].replace(/\.git$/,"");const api=`https://api.github.com/repos/${repo}/git/trees/${branch||"main"}?recursive=1`;const r=await pFetch(api,{headers:{Accept:"application/vnd.github+json"}});if(!r.ok)throw new Error("GitHub API : HTTP "+r.status+" (repo privé ? branche ?)");const j=await r.json();const files=(j.tree||[]).filter(t=>t.type==="blob"&&/\.(js|ts|json|env|ya?ml|txt|py|php|conf|example)$/i.test(t.path)).slice(0,25);const out=[];for(const f of files.slice(0,12)){try{const raw=`https://raw.githubusercontent.com/${repo}/${branch||"main"}/${f.path}`;const rr=await pFetch(raw);if(rr.ok)out.push({name:f.path,content:(await rr.text()).slice(0,60000)});}catch(e){}}if(!out.length)throw new Error("Aucun fichier lisible (repo vide/privé ?)");return out;}
function filesFromPaste(text){if(!text.trim())return[];const parts=text.split(/=====+\s*([^\n=]+)\s*=====+|---+\s*FILE:\s*([^\n]+)\s*---+/g);if(parts.length>1){const out=[];for(let i=1;i<parts.length;i+=3){const name=(parts[i]||parts[i+1]||"pasted-"+(out.length+1)).trim();const content=(parts[i+2]||"").trim();if(content)out.push({name,content});}if(out.length)return out;}if(/"dependencies"\s*:/.test(text))return[{name:"package.json",content:text}];return[{name:"pasted-source.txt",content:text}];}
function localExplain(f,target){return `Analyse locale (sans IA externe) — ${f.id} [${f.severity}] ${f.title}\nLieu : ${f.location||""}${f.func?" · Fonction "+f.func+"()":""}\nRisque : ${f.problem||"—"}\nCorrection : ${f.recommendation||"—"} — ${f.fixedCode||f.fix||"—"}\nVérification : ${f.verify||"Re-scan"}`;}
