function verifyAudits(prev,curr,older){const pm=new Map((prev.findings||[]).map(f=>[f.fingerprint||fingerprintOf(f),f]));const cm=new Map((curr.findings||[]).map(f=>[f.fingerprint||fingerprintOf(f),f]));const resolved=[],still=[],fresh=[];pm.forEach((f,fp)=>{if(cm.has(fp))still.push({prev:f,curr:cm.get(fp)});else resolved.push(f);});cm.forEach((f,fp)=>{if(!pm.has(fp))fresh.push(f);});const oldFp=new Set();(older||[]).forEach(a=>(a.findings||[]).forEach(f=>oldFp.add(f.fingerprint||fingerprintOf(f))));still.forEach(s=>{if(s.curr.status!=="DUPLICATE")s.curr.status="STILL_OPEN";});fresh.forEach(f=>{if(f.status==="DUPLICATE")return;f.status=oldFp.has(f.fingerprint||fingerprintOf(f))?"REGRESSED":"NEW";});return{resolved,still,fresh,delta:curr.score-prev.score};}
