function configOf(f){const t=String((f.title||"")+ " " +(f.category||"")).toLowerCase();if(/content-security-policy|csp|hsts|frame-options|nosniff|referrer|permissions-policy|opener-policy|cors|server header|redirect/i.test(f.title||""))return "Response headers (nginx / apache / application)";if(/cookie/i.test(f.title||""))return "Set-Cookie — serveur applicatif";if(/robots|security\.txt|\.env|\.git|server-status|wp-login|\/admin/i.test(f.title||""))return "Fichier / route exposée — docroot & routage";if(/form|csrf|input|validation/i.test(f.title||""))return "Formulaire / template concerné";if(f.file&&/package\.json|requirements/i.test(f.file))return f.file+" — dépendances";if(f.file&&/nginx|docker/i.test(f.file))return f.file+" — configuration infra";if(f.file)return f.file+" — code source";return "Configuration application";}
function cweFor(f){const d=String(f.dedup||"");const M={"tls":["CWE-319","Transmission en clair"],"hsts":["CWE-319","Transmission en clair"],"redir":["CWE-319","Transmission en clair"],"content-security-policy":["CWE-693","Mécanisme de protection manquant"],"x-frame-options":["CWE-1021","Clickjacking"],"x-content-type-options":["CWE-693","Mécanisme de protection manquant"],"referrer-policy":["CWE-200","Exposition d'information"],"permissions-policy":["CWE-693","Mécanisme de protection manquant"],"cross-origin-opener-policy":["CWE-693","Mécanisme de protection manquant"],"csp-weak":["CWE-693","Mécanisme de protection manquant"],"server-header":["CWE-200","Exposition d'information"],"cookie-secure":["CWE-614","Cookie sensible sans Secure"],"cookie-httponly":["CWE-1004","Cookie sensible sans HttpOnly"],"cookie-samesite":["CWE-352","CSRF"],"cors":["CWE-942","Politique cross-domain permissive"],"form-method":["CWE-1006","Mauvaise pratique de codage"],"input-validation":["CWE-20","Validation d'entrée insuffisante"],"csrf":["CWE-352","CSRF"],"generator":["CWE-200","Exposition d'information"],"emails":["CWE-200","Exposition d'information"],"comments":["CWE-615","Information exposée via commentaires"],"stacktrace":["CWE-209","Message d'erreur verbeux"],"robots":["CWE-200","Exposition d'information"],"exposed:/.git/HEAD":["CWE-538","Exposition de fichiers/dépôt"],"exposed:/.env":["CWE-200","Exposition d'information"],"jslibs":["CWE-1104","Composant tiers non maintenu"],"pkgjson":["CWE-1006","Mauvaise pratique de codage"],"infra":["CWE-16","Configuration"]};if(M[d])return M[d];if(/^secret:/.test(d))return ["CWE-798","Credentials en dur"];if(/^sast:eval/.test(d))return ["CWE-95","Injection via eval"];if(/sast:(innerHTML|document\.write)/.test(d))return ["CWE-79","Cross-Site Scripting (XSS)"];if(/^sast:SQL/.test(d))return ["CWE-89","Injection SQL"];if(/sast:(Hash|MD5)/.test(d))return ["CWE-328","Hachage faible"];if(/sast:URL http/.test(d))return ["CWE-319","Transmission en clair"];if(/sast:.*TLS/.test(d))return ["CWE-295","Validation de certificat insuffisante"];if(/sast:Credential/.test(d))return ["CWE-798","Credentials en dur"];if(/sast:.*(random|aléa)/i.test(d))return ["CWE-338","PRNG faible"];if(/^sast:/.test(d))return ["CWE-1006","Mauvaise pratique de codage"];if(/^dep:|^osv:/.test(d))return ["CWE-1104","Composant tiers vulnérable"];if(/^exposed:/.test(d))return ["CWE-200","Exposition d'information"];if(/^ai-origin:/.test(d))return ["—","Provenance : pas une faiblesse"];return ["—","Non classé"];}
function enrichV2(f,target){f.status=f.status||"OPEN";f.confidence=confidenceFor(f);f.endpoint=f.endpoint||endpointOf(f,target);f.configTarget=f.configTarget||configOf(f);if(f.actual===undefined)f.actual=String(f.evidence||"—").slice(0,300);if(f.expected===undefined)f.expected=String(f.fix||"—").slice(0,300);if(!f.explanation)f.explanation=f.problem||"—";const fd=fixDetailsFor(f);if(f.currentCode===undefined)f.currentCode=fd[0];if(f.fixedCode===undefined)f.fixedCode=fd[1];if(f.command===undefined)f.command=fd[2];const cw=cweFor(f);if(!f.cwe)f.cwe=cw[0];if(!f.cweName)f.cweName=cw[1];if(!f.cvssSrc)f.cvssSrc=f.osvId?"OSV":"indicatif";return f;}
function confidenceFor(f){const c=String(f.confidence||"").toUpperCase();if(c==="CONFIRMED"||c==="MEDIUM"||c==="REVIEW_REQUIRED")return c;const d=String(f.dedup||"").toLowerCase();if(/secret:(stripe live key|aws access key|private key|github token|mongo connection string|postgres connection string)/.test(d))return "CONFIRMED";if(/^(tls|hsts|redir|cors|exposed:\/.env|exposed:\/.git\/HEAD)$/.test(d))return "CONFIRMED";if(/^secret:/.test(d))return "HIGH";if(/^sast:/.test(d))return /eval|sql|tls/i.test(d)?"HIGH":"MEDIUM";if(/jslibs|generator|comments|emails|robots|form-method|input-validation|ai-origin/.test(d))return "REVIEW_REQUIRED";if(/csrf|stacktrace|csp-weak/.test(d))return "MEDIUM";return "HIGH";}
function fixDetailsFor(f){const t=String(f.title||""),d=String(f.dedup||""),code=String(f.code||f.evidence||"").slice(0,300);if(/^secret:/.test(d)){const v="process.env."+t.replace(/[^A-Za-z0-9]+/g,"_").toUpperCase().replace(/^_+|_+$/g,"").slice(0,28);return [code,v+" // secret hors du code (rotation si déjà exposé)",""];}if(/sast:eval/i.test(d))return [code,"const data = JSON.parse(input); // jamais eval() sur entrée externe",""];if(/innerHTML/i.test(t))return [code,"el.textContent = value; // ou DOMPurify.sanitize(value) avant innerHTML",""];if(/document\.write/i.test(t))return [code,"document.body.appendChild(document.createTextNode(value));",""];if(/SQL/i.test(t))return [code,'db.query("SELECT * FROM users WHERE id = ?", [id]); // requête paramétrée',""];if(/MD5|Hash faible/i.test(t))return [code,'crypto.createHash("sha256").update(x).digest("hex");',""];if(/random/i.test(t))return [code,'crypto.randomBytes(32).toString("hex"); // aléa cryptographique',""];if(/http:\/\//i.test(t))return [code,"https://… // chiffrement + HSTS",""];if(/TLS/i.test(t))return [code,"rejectUnauthorized: true // + CA valide",""];if(/^dep:/.test(d))return [code,String(f.fix||"").slice(0,200),String(f.fix||"").slice(0,120)];return [code,String(f.fix||"—").slice(0,300),""];}
function priorityActionFor(f){const t=String(f.title||"");if(/mongo|postgres/i.test(t))return "Rotation + secret manager";if(/secret|key|token|jwt|password|credential|private key/i.test(t))return "Rotation + variable d'environnement";if(/eval|sql|injection|xss|innerhtml|document\.write/i.test(t))return "Requête paramétrée / assainissement sortie";if(/dépendance/i.test(t))return "Mise à jour ("+String(f.fix||"npm update").slice(0,60)+")";if(/hsts|https|tls|redirect/i.test(t))return "Forcer HTTPS + HSTS";if(/csp|frame-options|nosniff|cors|cookie|serveur/i.test(t))return "Durcir headers / cookies";if(/csrf/i.test(t))return "Token CSRF + SameSite";if(/expos|robots|\.env|\.git|admin|server-status/i.test(t))return "Bloquer l'accès (403/404)";return String(f.recommendation||"Corriger puis re-scan").slice(0,80);}
function applyGrouping(F){F.forEach(f=>{if(f.status==="DUPLICATE")f.status="OPEN";f.duplicate_of=null;f.groupIds=null;});const by={};F.forEach(f=>{if(f.dedup&&f.dedup.indexOf("ai-origin:")===0)return;if(f.file&&f.line){const k=f.file+":"+f.line;(by[k]=by[k]||[]).push(f);}});Object.values(by).forEach(g=>{if(g.length<2)return;g.sort((a,b)=>(SEV_W[b.severity]||0)-(SEV_W[a.severity]||0));const p=g[0];p.groupIds=g.slice(1).map(x=>x.id);p.related_to=g.slice(1).map(x=>x.fingerprint||fingerprintOf(x));g.slice(1).forEach(x=>{x.status="DUPLICATE";x.duplicate_of=p.id;});});return F;}
function scoreWhy(prev,curr){const W=f=>!f||f.status==="DUPLICATE"?0:(SEV_W[f.severity]||0);const pm=new Map((prev.findings||[]).map(f=>[f.fingerprint||fingerprintOf(f),f]));const cm=new Map((curr.findings||[]).map(f=>[f.fingerprint||fingerprintOf(f),f]));const rows=[];new Set([...pm.keys(),...cm.keys()]).forEach(fp=>{const p=pm.get(fp),c=cm.get(fp);const d=W(p)-W(c);if(d!==0)rows.push({fp,p,c,d});});rows.sort((a,b)=>Math.abs(b.d)-Math.abs(a.d));const plus=rows.filter(r=>r.d>0).map(r=>r.p),minus=rows.filter(r=>r.d<0).map(r=>r.c);return{rows,plus,minus,delta:curr.score-prev.score};}
function statusPill(st){if(st==="RESOLVED")return `<span class="stRESOLVED">✅ RESOLVED</span>`;if(st==="NEW")return `<span class="stNEW">🆕 NEW</span>`;if(st==="REGRESSED")return `<span class="stNEW">🔁 REGRESSED</span>`;if(st==="DUPLICATE")return `<span class="pill info">🔗 DUPLICATE</span>`;if(st==="STILL_OPEN"||st==="STILL OPEN")return `<span class="stSTILL">❌ STILL OPEN</span>`;return `<span class="stOPEN">🔴 OPEN</span>`;}
function stepperHTML(active){return `<div class="steps">${STEPS.map((s,i)=>`<span class="${i<=active?"done":""}">${s}</span>`).join("")}</div>`;}
function verifyBannerHTML(cur){const prev=prevAuditFor(cur);if(!prev)return "";const older=auditsFor(cur.target).filter(a=>a.id!==cur.id&&a.id!==prev.id);const v=verifyAudits(prev,cur,older);const w=scoreWhy(prev,cur);return `<div class="card" style="margin-top:12px"><h3>Moteur 6/6 Vérification — ${esc(prev.id)} → ${esc(cur.id)}</h3><div class="row"><div class="kv"><div class="scoreRing" style="--p:${prev.score}%"><b>${prev.score}</b></div><span class="mut">BEFORE</span><span style="font-size:20px">→</span><div class="scoreRing" style="--p:${cur.score}%"><b>${cur.score}</b></div><span class="mut">AFTER</span><span class="pill ${v.delta>=0?"okk":"crit"}">${v.delta>=0?"+":""}${v.delta} Security Score</span></div></div><div class="row" style="margin-top:8px"><span class="mut">CRITICAL ${prev.counts.CRITICAL||0} → ${cur.counts.CRITICAL||0}</span><span class="mut">HIGH ${prev.counts.HIGH||0} → ${cur.counts.HIGH||0}</span><span class="mut">MEDIUM ${prev.counts.MEDIUM||0} → ${cur.counts.MEDIUM||0}</span></div><div class="row" style="margin-top:8px"><span class="stRESOLVED">✅ ${v.resolved.length} RESOLVED</span><span class="stSTILL">${v.still.length} STILL OPEN</span><span class="stNEW">${v.fresh.length} NEW</span><button class="btn ghost" id="gotoVerifyBtn">Détail vérification</button></div><div class="mut" style="margin-top:6px">Pourquoi ${cur.score} (était ${prev.score}, ${v.delta>=0?"+":""}${v.delta}) : ${w.rows.slice(0,4).map(r=>`${r.d>0?"+":"−"}${Math.abs(r.d)} ${(r.c||r.p).id} (${!r.c?"résolu":!r.p?"nouveau":r.c.status==="DUPLICATE"?"devenu doublon":r.p.status==="DUPLICATE"?"devenu principal":"modifié"})`).join(" · ")||"repondération interne"}</div></div></div>`;}
function renderDash(){const a=orgAudits();const tot=f=>a.reduce((s,x)=>s+(x.counts&&x.counts[f]||0),0);const last=a[0];$("#view-dash").innerHTML=`<div class="grid g6">
<div class="card"><h3>Security Score</h3><div class="kv"><div class="scoreRing" style="--p:${last?last.score:0}%"><b>${last?last.score:"—"}</b></div><div><div class="mut">${last?esc(last.target):"Aucun audit"}</div><div class="mut" style="font-size:12px">${last?esc(last.date):"Lancez votre premier audit"}</div></div></div></div>
<div class="card"><h3>Critical</h3><div class="big" style="color:var(--crit)">${tot("CRITICAL")}</div></div>
<div class="card"><h3>High</h3><div class="big" style="color:var(--high)">${tot("HIGH")}</div></div>
<div class="card"><h3>Medium</h3><div class="big" style="color:var(--med)">${tot("MEDIUM")}</div></div>
<div class="card"><h3>Low</h3><div class="big" style="color:var(--low)">${tot("LOW")}</div></div>
<div class="card"><h3>Passed</h3><div class="big" style="color:var(--ok)">${tot("PASSED")}</div></div></div>
<div class="card" style="margin-top:12px"><h3>Cycle KlirSecure — Détecter → Localiser → Expliquer → Corriger → Rapporter → Vérifier</h3><table><tr><th>Cible</th><th>Score</th><th>Findings</th><th>Date</th><th></th></tr>${a.map((x,i)=>`<tr><td>${esc(x.target)}</td><td><b>${x.score}/100</b></td><td>${totN(x)} findings</td><td class="mut">${esc(x.date||"")}</td><td class="noPrint"><button class="btn ghost" data-open="${i}">Ouvrir</button></td></tr>`).join("")}</table><div class="notice" style="margin-top:10px">Chaque finding garde un ID stable (<b>SEC-001, SEC-002…</b>) par cible. Le re-scan classe chaque ID en <b>RESOLVED / STILL OPEN / NEW</b>. Scans <b>passifs et autorisés uniquement</b>.</div></div>`;
$("#view-dash").querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>{store.current=store.audits[+b.dataset.open];renderResults();show("results");});}
function locLine(f,target){enrichV2(f,target);if(f.file)return `<div class="mut">📍 Localisation · <code>${esc(f.file)}</code> · Ligne <b>${f.line||"—"}</b> · Colonne <b>${f.col||"—"}</b>${f.func?` · Fonction <code>${esc(f.func)}()</code>`:""}</div><div class="mut">Endpoint · <code>${esc(f.endpoint)}</code> · Config · <code>${esc(f.configTarget)}</code></div>`;return `<div class="mut">📍 Localisation · URL <code>${esc(f.location||target)}</code></div><div class="mut">Endpoint · <code>${esc(f.endpoint)}</code> · Config · <code>${esc(f.configTarget)}</code></div>`;}
function findingCard(f,target,st){enrichV2(f,target);const shown=st||f.status||"OPEN";return `<div class="find"><div class="head"><b>Finding ${f.id}</b><span class="pill ${SEV_C[f.severity]||"info"}">${f.severity}</span><span class="pill info">${esc(f.category||"")}</span>${f.cwe&&f.cwe!=="—"?`<span class="pill info" title="${esc(f.cweName||"")}">CWE ${esc(String(f.cwe).replace("CWE-",""))}</span>`:""}<span class="mut">${f.cvssSrc==="OSV"?`CVSS ${f.cvss} (OSV)`:f.cvss?`Sév. ${f.cvss} (indicatif)`:"Sév. —"} · confiance ${esc(f.confidence||"—")}${f.occurrences>1?` · ×${f.occurrences}`:""}</span>${statusPill(shown)}</div>
<div style="margin:6px 0;font-weight:800">${esc(f.title)}</div>
${f.duplicate_of?`<div class="mut">🔗 Doublon de <b>${esc(f.duplicate_of)}</b> (même cause racine — voir finding principal) · related_to ${esc((f.fingerprint||""))}</div>`:""}${f.groupIds&&f.groupIds.length?`<div class="mut">🔗 Problème racine — regroupe ${f.groupIds.length} détection(s) : <b>${f.groupIds.map(esc).join(", ")}</b> (duplicate_of → ${f.id})</div>`:""}
${locLine(f,target)}
${f.code?`<div class="mut" style="font-size:11px;margin-top:6px">CODE CONCERNÉ</div><pre>${esc(f.code)}</pre>`:""}
<div class="grid g2" style="margin-top:8px"><div><div class="mut" style="font-size:11px">1 · LOCALISATION PRÉCISE</div><div class="mut" style="font-size:12px">Fichier/URL : <code>${esc(f.file||f.location||target)}</code>${f.line?" · L"+f.line+(f.col?", C"+f.col:""):""}${f.func?" · "+esc(f.func)+"()":""}</div><div class="mut" style="font-size:12px">Endpoint : <code>${esc(f.endpoint)}</code></div><div class="mut" style="font-size:11px;margin-top:6px">2 · EVIDENCE TECHNIQUE</div><div class="mut" style="font-size:11px">PREUVE</div><pre>${esc(f.evidence||"—")}</pre><div class="mut" style="font-size:11px">VALEUR ACTUELLE</div><pre>${esc(f.actual||"—")}</pre><div class="mut" style="font-size:11px">VALEUR ATTENDUE</div><pre>${esc(f.expected||"—")}</pre></div>
<div><div class="mut" style="font-size:11px">3 · CORRECTION EXPLOITABLE</div><div class="mut" style="font-size:11px">PROBLÈME</div><div>${esc(f.explanation||"—")}</div><div class="mut" style="font-size:11px;margin-top:6px">POURQUOI C'EST DANGEREUX</div><div>${esc(f.problem||"—")}</div><div class="mut" style="font-size:11px;margin-top:6px">CODE ACTUEL</div><pre>${esc(f.currentCode||f.code||"—")}</pre><div class="mut" style="font-size:11px">CODE CORRIGÉ</div><pre>${esc(f.fixedCode||f.fix||"—")}</pre><div class="mut" style="font-size:11px">FICHIER CONCERNÉ</div><div><code>${esc(f.file||f.location||target)}</code></div>${f.command?`<div class="mut" style="font-size:11px;margin-top:6px">COMMANDE</div><pre>${esc(f.command)}</pre>`:""}<div class="mut" style="font-size:11px;margin-top:6px">MÉTHODE DE VÉRIFICATION</div><div>${esc(f.verify||"Nouveau scan → RESOLVED")}</div></div></div>
<div class="row noPrint" style="margin-top:8px"><button class="btn ghost" data-ai="${f.id}">Expliquer avec IA</button><span class="mut" id="ai-${f.id}"></span></div><div id="aiout-${f.id}"></div></div>`;}
function sarifLevel(s){return s==="CRITICAL"||s==="HIGH"?"error":s==="MEDIUM"?"warning":"note";}
function auditToSarif(a){const rules=[];const seen={};(a.findings||[]).forEach(f=>{const rid="KS/"+String(f.dedup||"misc").replace(/[^A-Za-z0-9_:\-./]/g,"_").slice(0,80);if(seen[rid])return;seen[rid]=1;const cwe=/^CWE-\d+/.test(f.cwe||"")?f.cwe.match(/\d+/)[0]:null;rules.push({id:rid,name:rid,shortDescription:{text:String(f.title||rid).slice(0,200)},fullDescription:{text:`${f.cweName||f.category||""} — ${f.recommendation||""}`.slice(0,500)},help:{text:`Correction : ${f.fix||f.fixedCode||"—"}\nVérification : ${f.verify||"Re-scan"}`.slice(0,800),markdown:`**Correction :** ${f.fix||f.fixedCode||"—"}\n\n**Vérification :** ${f.verify||"Re-scan"}`.slice(0,1000)},helpUri:cwe?`https://cwe.mitre.org/data/definitions/${cwe}.html`:"https://owasp.org/www-project-top-ten/",properties:{cwe:f.cwe||"—",confidence:f.confidence||"—",cvss:f.cvss??null,cvssSrc:f.cvssSrc||"indicatif"}});});return{version:"2.1.0",$schema:"https://json.schemastore.org/sarif-2.1.0.json",runs:[{tool:{driver:{name:"KlirSecure Audit",version:"V3-enterprise",informationUri:"https://perchance.org",rules}},results:(a.findings||[]).filter(f=>f.status!=="DUPLICATE").map(f=>({ruleId:"KS/"+String(f.dedup||"misc").replace(/[^A-Za-z0-9_:\-./]/g,"_").slice(0,80),level:sarifLevel(f.severity),message:{text:`[${f.id} ${f.severity}] ${f.title} — ${f.problem||""}`.slice(0,600)},locations:[{physicalLocation:{artifactLocation:{uri:String(f.file||f.location||a.target).slice(0,300)},region:{startLine:f.line||1,startColumn:f.col||1}}}],partialFingerprints:{klirsecurefp:String(f.fingerprint||"")},properties:{findingId:f.id,status:f.status||"OPEN",occurrences:f.occurrences||1}}))}]};}
function downloadSarif(){const a=store.current;if(!a)return;const blob=new Blob([JSON.stringify(auditToSarif(a),null,2)],{type:"application/json"});const u=URL.createObjectURL(blob);const l=document.createElement("a");l.href=u;l.download="klirsecure-"+(a.id||"audit")+".sarif";l.click();}
function printReportV2(){const a=store.current;if(!a)return;let pr=document.querySelector("#printReport");if(!pr){pr=document.createElement("div");pr.id="printReport";document.querySelector(".wrap").appendChild(pr);}(a.findings||[]).forEach(f=>enrichV2(f,a.target));applyGrouping(a.findings||[]);const prev=prevAuditFor(a);const v=prev?verifyAudits(prev,a,auditsFor(a.target).filter(x=>x.id!==a.id&&x.id!==prev.id)):null;const pri=[...(a.findings||[])].filter(f=>f.status!=="DUPLICATE").sort((x,y)=>(SEV_W[y.severity]||0)-(SEV_W[x.severity]||0));const c=a.counts||countsOf(a.findings||[]);pr.innerHTML=`<div class="prHead"><h1>🔒 KlirSecure — Rapport d'audit sécurité (V2)</h1><div>Organisation : <b>${esc(orgName(a.orgId))}</b> · Cible : <b>${esc(a.target)}</b> · ${esc(a.id||"")} · ${esc(a.date||"")} · CONFIDENTIAL</div><div>Score : <b>${a.score}/100</b> · CRITICAL ${c.CRITICAL||0} · HIGH ${c.HIGH||0} · MEDIUM ${c.MEDIUM||0} · LOW ${c.LOW||0} · INFO ${c.INFO||0} · PASSED ${c.PASSED||0}</div></div><div class="prSec"><h2>1 · Résumé exécutif</h2><div>${esc(a.summary||"—")}</div></div>${v?`<div class="prSec"><h2>2 · Comparaison avec l'audit précédent (${esc(prev.id)} → ${esc(a.id)})</h2><div>Score : <b>${prev.score} → ${a.score}</b> (${v.delta>=0?"+":""}${v.delta}) · Critical ${prev.counts.CRITICAL||0} → ${a.counts.CRITICAL||0} · High ${prev.counts.HIGH||0} → ${a.counts.HIGH||0} · Medium ${prev.counts.MEDIUM||0} → ${a.counts.MEDIUM||0}</div><div>${v.resolved.map(f=>`${f.id} → RESOLVED`).join(" · ")}${v.still.length?" · "+v.still.map(s=>`${s.curr.id} → STILL OPEN`).join(" · "):""}${v.fresh.length?" · "+v.fresh.map(f=>`${f.id} → NEW`).join(" · "):""}</div></div>`:`<div class="prSec"><h2>2 · Comparaison</h2><div>Premier audit de cette cible — la comparaison apparaîtra après le re-scan de vérification.</div></div>`}<div class="prSec"><h2>3 · Findings (${(a.findings||[]).length})</h2>${(a.findings||[]).map(f=>`<div class="prFind"><h3>${f.id} · [${f.severity}] ${esc(f.title)} · ${statusPill(f.status||"OPEN")}</h3><div class="prMut">Emplacement</div><div>${esc(f.file||f.location||a.target)}${f.line?" · Ligne "+f.line+(f.col?", colonne "+f.col:""):""}${f.func?" · Fonction "+esc(f.func)+"()":""} · Endpoint ${esc(f.endpoint)} · Config ${esc(f.configTarget)}</div><div class="prMut">Evidence</div><div>Preuve : ${esc(f.evidence||"—")}</div><div>Actuelle : ${esc(f.actual||"—")} → Attendue : ${esc(f.expected||"—")}</div><div class="prMut">Correction</div><div>${esc(f.explanation||"—")} — ${esc(f.recommendation||"—")}</div><div>Exemple : ${esc(f.fix||"—")}</div><div class="prMut">Vérification</div><div>${esc(f.verify||"Nouveau scan → RESOLVED")}</div></div>`).join("")||"<div>Aucune finding.</div>"}</div><div class="prSec"><h2>4 · Actions prioritaires</h2><table><tr><th>Priorité</th><th>Finding</th><th>Action</th></tr>${pri.slice(0,12).map((f,i)=>`<tr><td>${(SEV_W[f.severity]||0)>=10?"🔴":"🟠"} ${i+1}</td><td>${f.id} · ${esc(f.title)}</td><td>${esc(priorityActionFor(f))}</td></tr>`).join("")}</table></div>${(a.passed||[]).length?`<div class="prSec"><h2>5 · Contrôles passés (${a.passed.length})</h2><div>${a.passed.map(esc).join(" · ")}</div></div>`:""}`;window.print();}
function renderResults(){const a=store.current;if(a&&a.findings)applyGrouping(a.findings);if(!a){$("#view-results").innerHTML=`<div class="card">Aucun audit sélectionné. <button class="btn ghost" onclick="document.querySelector('[data-view=new]').click()">Nouvel audit</button></div>`;return;}const c=a.counts||countsOf(a.findings||[]);$("#view-results").innerHTML=`
${stepperHTML(4)}
<div class="card"><div class="row"><div class="scoreRing" style="--p:${a.score}%"><b>${a.score}</b></div>
<div><h2 style="margin:0">WEB APPLICATION SECURITY AUDIT</h2><div class="mut">Cible : <b>${esc(a.target)}</b> · ${esc(a.date||"")} · ${esc(a.id||"")} · <span class="pill okk">CONFIDENTIAL</span></div>
<div class="row" style="margin-top:6px"><span class="pill crit">CRITICAL ${c.CRITICAL||0}</span><span class="pill high">HIGH ${c.HIGH||0}</span><span class="pill med">MEDIUM ${c.MEDIUM||0}</span><span class="pill low">LOW ${c.LOW||0}</span><span class="pill info">INFO ${c.INFO||0}</span><span class="pill okk">PASSED ${c.PASSED||a.passedCount||0}</span></div></div>
<div style="margin-left:auto" class="row noPrint"><button class="btn ghost" id="execBtn">Résumé exécutif IA</button><button class="btn ghost" id="jsonBtn">JSON</button><button class="btn ghost" id="sarifBtn">SARIF</button><button class="btn" id="pdfBtn">PDF Report</button><button class="btn ghost" id="verifyBtn">↻ Vérifier</button></div></div>
${a.config&&a.config.osv&&a.config.osv.status!=="skipped"?`<div class="mut" style="font-size:12px;margin-bottom:6px">Base vulnérabilités : OSV.dev · consultée le ${esc(a.config.osv.checkedAt||"—")} · statut : ${esc(a.config.osv.status||"—")}</div>`:""}<div class="notice" style="margin-top:10px"><b>Résumé exécutif</b><div id="execOut" class="mut">${esc(a.summary||"—")}</div></div></div>
${verifyBannerHTML(a)}
<div class="tabs noPrint" id="sevTabs"><button data-s="ALL" class="on">Tous (${(a.findings||[]).length})</button>${["CRITICAL","HIGH","MEDIUM","LOW","INFO"].map(s=>`<button data-s="${s}">${s} (${c[s]||0})</button>`).join("")}</div>
<div id="findList">${(a.findings||[]).map(f=>findingCard(f,a.target)).join("")||"<div class=card>Aucune finding — cible saine sur les modules testés.</div>"}</div>
${(a.passed||[]).length?`<div class="card"><h3>Passed (${a.passed.length})</h3><div class="mut">${a.passed.map(esc).join(" · ")}</div></div>`:""}`;
const list=()=>[...$("#view-results").querySelectorAll(".find")];
$("#sevTabs").querySelectorAll("button").forEach(b=>b.onclick=()=>{$("#sevTabs").querySelectorAll("button").forEach(x=>x.classList.remove("on"));b.classList.add("on");const s=b.dataset.s;list().forEach(el=>{el.style.display=(s==="ALL"||el.innerHTML.includes(">"+s+"<"))?"":"none";});});
$("#view-results").querySelectorAll("[data-ai]").forEach(b=>b.onclick=async()=>{const f=a.findings.find(x=>x.id===b.dataset.ai);$("#ai-"+f.id).textContent="Analyse IA…";const t=await aiExplain(f,a.target);$("#aiout-"+f.id).innerHTML=`<div class="notice" style="margin-top:8px"><b>AI Security Analyst</b><div>${esc(t)}</div></div>`;$("#ai-"+f.id).textContent="";});
$("#execBtn").onclick=async()=>{$("#execOut").textContent="Génération IA…";$("#execOut").textContent=await aiSummary(a);store.current.summary=$("#execOut").textContent;save();};
$("#jsonBtn").onclick=()=>{const blob=new Blob([JSON.stringify(a,null,2)],{type:"application/json"});const u=URL.createObjectURL(blob);const l=document.createElement("a");l.href=u;l.download="klirsecure-"+(a.id||"audit")+".json";l.click();};
$("#sarifBtn").onclick=()=>downloadSarif();
$("#pdfBtn").onclick=()=>printReportV2();
$("#verifyBtn").onclick=()=>runVerify();
const gv=$("#gotoVerifyBtn");if(gv)gv.onclick=()=>{renderCompare(a.target);show("compare");};}
function renderMap(){const a=store.current;if(!a||!a.findings){$("#view-map").innerHTML=`<div class="card">Lancez un audit pour voir la Remediation Map.</div>`;return;}const groups={};a.findings.forEach(f=>{const file=f.file||(f.location||"").split(" — ")[0].split(" (")[0];groups[file]=groups[file]||[];groups[file].push(f);});$("#view-map").innerHTML=`${stepperHTML(3)}<div class="card"><h3>Remediation Map — ${esc(a.target)} (${a.score}/100)</h3>${Object.entries(groups).map(([file,fs],i)=>`<div class="find"><div class="head"><b>${String(i+1).padStart(2,"0")}</b><code>${esc(file)}</code><span class="pill ${SEV_C[fs[0].severity]}">${fs[0].severity}</span><span class="mut">${fs.length} finding(s)</span></div>${fs.map(f=>`<div class="row" style="margin-top:6px"><span class="mut">${f.id}</span><span>${esc(f.title)}</span><span class="mut">${f.line?"L"+f.line:""}</span><button class="btn ghost" data-goto="${f.id}">Open Finding → ${esc(f.location||"")}</button></div>`).join("")}</div>`).join("")}</div>`;
$("#view-map").querySelectorAll("[data-goto]").forEach(b=>b.onclick=()=>{show("results");setTimeout(()=>{const el=[...document.querySelectorAll(".find")].find(e=>e.innerHTML.includes(b.dataset.goto));if(el)el.scrollIntoView({behavior:"smooth",block:"center"});},100);});}
function renderCompare(forceTarget){const a=orgAudits();a.forEach(x=>{if(x.findings)applyGrouping(x.findings);});const targets=[...new Set(a.map(x=>x.target))];const selT=forceTarget||targets[0];const list=auditsFor(selT||"");const A=list[1]||null,B=list[0]||null;let vHtml="";if(A&&B){const v=verifyAudits(A,B,auditsFor(selT||"").slice(2));vHtml=`<div class="card" style="margin-top:12px"><h3>BEFORE ${esc(A.id)} (${A.score}/100) → AFTER ${esc(B.id)} (${B.score}/100)</h3><div class="row"><span class="mut">Critical ${A.counts.CRITICAL||0} → ${B.counts.CRITICAL||0}</span><span class="mut">High ${A.counts.HIGH||0} → ${B.counts.HIGH||0}</span><span class="mut">Medium ${A.counts.MEDIUM||0} → ${B.counts.MEDIUM||0}</span><span class="pill ${v.delta>=0?"okk":"crit"}">Score ${A.score} → ${B.score} (${v.delta>=0?"+":""}${v.delta})</span><button class="btn" id="reVerifyBtn">↻ Nouveau scan de vérification</button></div><div class="row" style="margin-top:8px"><span class="stRESOLVED">✅ ${v.resolved.length} RESOLVED</span><span class="stSTILL">${v.still.length} STILL OPEN</span><span class="stNEW">${v.fresh.length} NEW</span></div><table style="margin-top:10px"><tr><th>ID</th><th>Finding</th><th>Statut</th></tr>${v.resolved.map(f=>`<tr><td class="mut">${f.id}</td><td>${esc(f.title)}</td><td><span class="stOPEN">${f.id} ❌ OPEN</span> → <span class="stRESOLVED">✅ RESOLVED</span></td></tr>`).join("")}${v.still.map(s=>`<tr><td class="mut">${s.curr.id}</td><td>${esc(s.curr.title)}</td><td><span class="stSTILL">❌ STILL OPEN</span></td></tr>`).join("")}${v.fresh.map(f=>`<tr><td class="mut">${f.id}</td><td>${esc(f.title)}</td><td><span class="stNEW">${f.status==="REGRESSED"?"🔁 REGRESSED":"🆕 NEW"}</span></td></tr>`).join("")||""}</table></div>`;}else{vHtml=`<div class="card" style="margin-top:12px">Un seul audit pour cette cible. Corrigez puis cliquez <b>Vérifier</b> pour obtenir BEFORE → AFTER et RESOLVED / STILL OPEN / NEW.<div class="row" style="margin-top:8px"><button class="btn" id="reVerifyBtn">↻ Nouveau scan de vérification</button></div></div>`;}
$("#view-compare").innerHTML=`${stepperHTML(5)}<div class="card"><h3>Moteur 6/6 Vérification — cycle de sécurité</h3><div class="row"><select id="cmpT">${targets.map(t=>`<option ${t===selT?"selected":""}>${esc(t)}</option>`).join("")}</select><select id="cmpA">${a.map((x,i)=>`<option value="${i}">${esc(x.target)} · ${x.score} (${esc(x.date||"")})</option>`).join("")}</select><select id="cmpB">${a.map((x,i)=>`<option value="${i}" ${i===1?"selected":""}>${esc(x.target)} · ${x.score} (${esc(x.date||"")})</option>`).join("")}</select><button class="btn" id="cmpGo">Comparer</button></div><div id="cmpOut" style="margin-top:10px"></div></div>${vHtml}`;
$("#cmpT").onchange=e=>renderCompare(e.target.value);
const rv=$("#reVerifyBtn");if(rv)rv.onclick=()=>runVerify();
$("#cmpGo").onclick=()=>{const X=a[+$("#cmpA").value],Y=a[+$("#cmpB").value];if(!X||!Y)return;const vv=verifyAudits(X,Y,[]);$("#cmpOut").innerHTML=`<div class="kv"><div class="scoreRing" style="--p:${X.score}%"><b>${X.score}</b></div><div style="font-size:24px">→<br><span class="pill ${vv.delta>=0?"okk":"crit"}">${vv.delta>=0?"+":""}${vv.delta}</span></div><div class="scoreRing" style="--p:${Y.score}%"><b>${Y.score}</b></div></div><table style="margin-top:10px"><tr><th></th><th>${esc(X.id)} → ${esc(Y.id)}</th></tr>${["CRITICAL","HIGH","MEDIUM","LOW","INFO"].map(k=>`<tr><td>${k}</td><td>${X.counts[k]||0} → ${Y.counts[k]||0}</td></tr>`).join("")}</table><div class="row" style="margin-top:8px"><span class="stRESOLVED">✅ ${vv.resolved.length} RESOLVED</span><span class="stSTILL">${vv.still.length} STILL OPEN</span><span class="stNEW">${vv.fresh.length} NEW</span></div>`;};}
function renderHistory(){const HL=orgAudits();const byT={};HL.forEach(a=>{(byT[a.target]=byT[a.target]||[]).push(a);});const evo=Object.entries(byT).filter(([t,l])=>l.length>1).map(([t,l])=>{const ch=[...l].reverse();const d=ch[ch.length-1].score-ch[0].score;return `<div class="card"><h3>Évolution — ${esc(t)}</h3><div class="mut">${ch.map((x,i)=>"Audit #"+(i+1)).join(" ↓ ")}</div><div style="font-size:20px;font-weight:900">${ch.map(x=>x.score).join(" → ")} <span class="pill ${d>=0?"okk":"crit"}">${d>=0?"+":""}${d}</span></div><div class="mut">évolution de la sécurité</div></div>`;}).join("");$("#view-history").innerHTML=evo+`<div class="card"><h3>Historique des audits</h3><table><tr><th>ID</th><th>Cible</th><th>Score</th><th>C/H/M/L</th><th>Date</th><th></th></tr>${HL.map((x,i)=>`<tr><td class="mut">${esc(x.id||"")}</td><td>${esc(x.target)}</td><td><b>${x.score}</b></td><td>${x.counts.CRITICAL||0}/${x.counts.HIGH||0}/${x.counts.MEDIUM||0}/${x.counts.LOW||0}</td><td class="mut">${esc(x.date||"")}</td><td class="noPrint"><button class="btn ghost" data-h="${i}">Ouvrir</button>${can("manage")?` <button class="btn warn" data-del="${i}">Suppr</button>`:""}</td></tr>`).join("")}</table></div>${authLogHtml()}`;
$("#view-history").querySelectorAll("[data-h]").forEach(b=>b.onclick=()=>{store.current=HL[+b.dataset.h];renderResults();renderMap();show("results");});
$("#view-history").querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{const t=HL[+b.dataset.del];if(!can("manage")){alert("Admin requis.");return;}store.audits.splice(store.audits.indexOf(t),1);save();refreshAll();});}
function refreshAll(){syncSessionUI();renderDash();renderResults();renderMap();renderCompare();renderHistory();renderOrg();}
function show(v){["dash","new","results","map","compare","history","org"].forEach(x=>$("#view-"+x).hidden=x!==v);document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("on",b.dataset.view===v));window.scrollTo({top:0});}
function pushAudit(a){a.orgId=a.orgId||sessionOrg();store.audits.unshift(a);store.current=a;logAuth(a);save();refreshAll();}
function buildAudit(target,type,findings,passed,config,ms){assignStableIds(target,findings);findings.forEach(f=>enrichV2(f,target));applyGrouping(findings);const score=scoreOf(findings);return{id:"AUDIT-"+Date.now().toString(36).toUpperCase().slice(-6),target,type,date:new Date().toISOString().slice(0,10)+" "+new Date().toLocaleTimeString().slice(0,5),score,counts:{...countsOf(findings),PASSED:passed.length},findings,passed,config,summary:`Audit ${target} : score ${score}/100, ${findings.length} findings (${countsOf(findings).CRITICAL} critical, ${countsOf(findings).HIGH} high).`+(ms?` (${ms}ms).`:"")};}
async function runWeb(){let target=$("#targetInput").value.trim();if(!/^https?:\/\//i.test(target))target="https://"+target;if(!$("#authWebChk").checked){alert("Cochez la confirmation d'autorisation pour auditer cette cible.");return;}if(!can("audit")){alert("Rôle lecteur : consultation seule.");return;}const qcw=quotaCheck();if(!qcw.ok){alert(qcw.msg);return;}const sel=new Set([...$("#webChecks").querySelectorAll("input:checked")].map(i=>i.value));if(!sel.size){alert("Sélectionnez au moins un module.");return;}$("#scanLog").innerHTML="";setBar(2,"Moteur 1/6 Scanner…","web");try{const r=await scanWeb(target,sel);setBar(100,"Terminé en "+r.ms+"ms","done");const a=buildAudit(target,"web",r.findings,r.passed,{modules:[...sel]},r.ms);pushAudit(a);log(`Moteurs 2-5 : evidence + localisation + score ${a.score}/100 · ${r.findings.length} findings`);show("results");}catch(e){setBar(0,"Erreur : "+e.message,"error");log("ERREUR : "+e.message);alert(e.message);}}
async function runCode(){if(!$("#authCodeChk").checked){alert("Cochez la confirmation d'autorisation.");return;}if(!can("audit")){alert("Rôle lecteur : consultation seule.");return;}const qcc=quotaCheck();if(!qcc.ok){alert(qcc.msg);return;}const sel=new Set([...$("#codeChecks").querySelectorAll("input:checked")].map(i=>i.value));$("#scanLog").innerHTML="";setBar(5,"Moteur 1/6 Scanner code…","code");log("Moteur 2/6 Evidence : secrets masqués…");let files=filesFromPaste($("#codeInput").value);if(!files.length){alert("Collez du code ou chargez un repo GitHub.");return;}setBar(40,"Moteur 3/6 Localisation : "+files.length+" fichiers","code");await sleep(200);let findings=scanCodeFiles(files,sel);setBar(85,"Base OSV.dev (temps réel)…","code");let osvInfo={label:"OSV.dev",status:"skipped",checkedAt:"—"};try{const oe=await enrichDepsOSV(files,sel);osvInfo={label:"OSV.dev",status:oe.status,checkedAt:oe.checkedAt||"—"};if(oe.status.indexOf("ok")===0&&oe.covered.length)findings=findings.filter(f=>{const d=String(f.dedup||"");if(d.indexOf("dep:")===0&&oe.covered.includes(d.slice(4).toLowerCase()))return false;if(d==="dep:py"&&files.some(x=>/requirements\.txt$/.test(x.name)))return false;return true;});findings.push(...oe.findings);}catch(e){log("OSV : "+(e.message||e)+" → repli base locale.");}setBar(100,"Terminé","done");const label=$("#repoInput").value.trim()||(files[0]?files[0].name:"projet");pushAudit(buildAudit(label,"code",findings,[],{modules:[...sel],osv:osvInfo,snapshot:files.map(f=>({name:f.name,content:f.content.slice(0,20000)}))}));show("results");}
async function runVerify(){const cur=store.current;if(!cur){alert("Aucun audit à vérifier.");return;}if(!can("audit")){alert("Rôle lecteur : consultation seule.");return;}show("new");await sleep(50);if(cur.type==="web"){$("#targetInput").value=cur.target;$("#authWebChk").checked=true;if(cur.config&&cur.config.modules){$("#webChecks").querySelectorAll("input").forEach(i=>i.checked=cur.config.modules.includes(i.value));}log("Moteur 6/6 Vérification : re-scan de "+cur.target);await runWeb();}else{const snap=(cur.config&&cur.config.snapshot)||[];if(!$("#codeInput").value.trim()&&snap.length)$("#codeInput").value=snap.map(f=>`===== ${f.name} =====\n${f.content}`).join("\n");if(cur.config&&cur.config.modules){$("#codeChecks").querySelectorAll("input").forEach(i=>i.checked=cur.config.modules.includes(i.value));}$("#repoInput").value=cur.target;$("#authCodeChk").checked=true;log("Moteur 6/6 Vérification : collez le code CORRIGÉ puis relancez. Contenu actuel pré-rempli.");alert("Collez votre code CORRIGÉ dans la zone (pré-rempli avec l'ancien), puis cliquez ANALYZE PROJECT. La comparaison BEFORE → AFTER apparaîtra dans Vérifier.");}renderCompare(cur.target);}
const PLANS={solo:{label:"Solo — TPE",quota:5},pme:{label:"PME",quota:30},affaires:{label:"Affaires — ETI",quota:200},agence:{label:"Agence / ESN",quota:1000}};
function sessionOrg(){return (store.session&&store.session.orgId)||((store.orgs||[])[0]&&store.orgs[0].id)||"org-default";}
function sessionUser(){const us=store.users||[];return us.find(u=>u.id===(store.session&&store.session.userId))||us.find(u=>u.orgId===sessionOrg())||us[0]||{id:"u-admin",name:"Admin",role:"admin",orgId:sessionOrg()};}
function can(act){const r=sessionUser().role||"lecteur";if(r==="admin")return true;if(r==="auditeur")return act==="audit"||act==="verify"||act==="export"||act==="view";return act==="view"||act==="export";}
function orgAudits(){const o=sessionOrg();return store.audits.filter(a=>!a.orgId||a.orgId===o);}
function orgName(id){const o=(store.orgs||[]).find(x=>x.id===id);return o?o.name:"—";}
function currentOrg(){return (store.orgs||[]).find(o=>o.id===sessionOrg())||{id:sessionOrg(),name:"—",type:"PME",plan:"solo",legal:{},cgu:[]};}
function monthKey(d){return String(d||"").slice(0,7);}
function quotaCheck(){const o=currentOrg();const p=PLANS[o.plan]||PLANS.solo;const mk=monthKey(new Date().toISOString().slice(0,10));const n=orgAudits().filter(a=>monthKey(a.date)===mk).length;if(n>=p.quota)return{ok:false,msg:`Quota ${p.label} atteint (${p.quota} audits/mois pour ${o.name}). Changez de plan dans Organisation.`};return{ok:true,n,quota:p.quota};}
function saveOrgs(){try{localStorage.setItem("klirsecure_orgs",JSON.stringify({orgs:store.orgs||[],users:store.users||[],session:store.session||{},ops:store.ops||{}}));}catch(e){}try{if(root&&root.kv)root.kv.orgs.set("all",{orgs:store.orgs||[],users:store.users||[],session:store.session||{},ops:store.ops||{}});}catch(e){}}
async function loadOrgs(){try{const r=localStorage.getItem("klirsecure_orgs");if(r){const o=JSON.parse(r);store.orgs=o.orgs||[];store.users=o.users||[];store.session=o.session||{};store.ops=o.ops||{};}}catch(e){}try{if(root&&root.kv){const o=await root.kv.orgs.get("all");if(o&&!(store.orgs||[]).length){store.orgs=o.orgs||[];store.users=o.users||[];store.session=o.session||{};store.ops=o.ops||{};}}}catch(e){}if(!(store.orgs||[]).length){const oid="org-"+Math.random().toString(36).slice(2,7);store.orgs=[{id:oid,name:"Ma société",type:"PME",plan:"solo",legal:{},cgu:[],createdAt:new Date().toISOString().slice(0,10)}];store.users=[{id:"u-"+Math.random().toString(36).slice(2,7),name:"Admin",email:"",role:"admin",orgId:oid}];store.session={orgId:oid,userId:store.users[0].id};}store.audits.forEach(a=>{if(!a.orgId)a.orgId=store.session.orgId||store.orgs[0].id;});if(!store.session)store.session={orgId:store.orgs[0].id,userId:(store.users[0]||{}).id};saveOrgs();}
function switchOrg(id){store.session={...(store.session||{}),orgId:id};const u=(store.users||[]).find(x=>x.orgId===id&&x.role==="admin")||(store.users||[]).find(x=>x.orgId===id);if(u)store.session.userId=u.id;const l=orgAudits();store.current=l[0]||null;saveOrgs();refreshAll();show("dash");}
function switchUser(id){store.session={...(store.session||{}),userId:id};const u=sessionUser();if(u&&u.orgId&&u.orgId!==store.session.orgId){store.session.orgId=u.orgId;const l=orgAudits();store.current=l[0]||null;}saveOrgs();refreshAll();}
function syncSessionUI(){const os=$("#orgSel"),us=$("#userSel");if(!os||!us)return;os.innerHTML=(store.orgs||[]).map(o=>`<option value="${o.id}">${esc(o.name)} · ${(PLANS[o.plan]||{}).label||o.plan}</option>`).join("");os.value=sessionOrg();us.innerHTML=(store.users||[]).map(u=>`<option value="${u.id}">${esc(u.name)} (${u.role} · ${esc(orgName(u.orgId))})</option>`).join("");us.value=(store.session&&store.session.userId)||"";}
function contractText(){const o=currentOrg();const L=o.legal||{};const p=PLANS[o.plan]||PLANS.solo;return `# Contrat-cadre de prestation d'audit sécurité — KlirSecure\n\n**Prestataire :** [Votre société, SIREN] — CGV v2026-09-30\n**Client :** ${L.raison||o.name} — SIREN ${L.siren||"[à compléter]"} — DPO ${L.dpo||"[à compléter]"}\n**Type :** ${o.type} — **Plan :** ${p.label} (${p.quota} audits/mois)\n\n## 1. Périmètre\nAudits passifs autorisés uniquement, tracés au journal des autorisations.\n\n## 2. Livrables\nRapports PDF/JSON/SARIF, score, findings CWE, re-scan de vérification.\n\n## 3. Limites\nPas de garantie d'absence de vulnérabilités. Scores « indicatif » = estimations internes ; « OSV » = base externe temps réel.\n\n## 4. Données\nDPA applicable. Mode local-only ${prefs.localOnly?"activé":"disponible sur demande (zéro transfert IA externe)"}.\n\n## 5. Responsabilité\nPlafonnée au montant 12 mois (cf. CGV). Acceptations CGV : ${((o.cgu||[]).map(g=>g.v+" par "+g.by+" le "+g.date).join(" ; "))||"—"}\n\nSignatures : __________________ / __________________\n`;}
function backupAll(){const data={app:"klirsecure",exportedAt:new Date().toISOString(),orgs:store.orgs,users:store.users,session:store.session,audits:store.audits,authLog,prefs,idReg,ops:store.ops||{}};store.ops={...(store.ops||{}),lastBackup:data.exportedAt};saveOrgs();const b=new Blob([JSON.stringify(data)],{type:"application/json"});const u=URL.createObjectURL(b);const l=document.createElement("a");l.href=u;l.download="klirsecure-backup-"+data.exportedAt.slice(0,10)+".json";l.click();renderOrg();}
function restoreAll(file){const rd=new FileReader();rd.onload=()=>{try{const d=JSON.parse(rd.result);if(d.app!=="klirsecure")throw new Error("Fichier non reconnu");store.orgs=d.orgs||store.orgs;store.users=d.users||store.users;store.session=d.session||store.session;store.audits=d.audits||[];store.current=store.audits[0]||null;if(d.authLog)authLog=d.authLog;if(d.prefs)prefs={...prefs,...d.prefs};if(d.idReg)idReg=d.idReg;if(d.ops)store.ops=d.ops;save();savePrefs();saveIds();saveOrgs();refreshAll();}catch(e){alert("Restauration impossible : "+e.message);}};rd.readAsText(file);}
function renderOrg(){const box=$("#view-org");if(!box)return;const o=currentOrg();const L=o.legal||{};const p=PLANS[o.plan]||PLANS.solo;const mk=monthKey(new Date().toISOString().slice(0,10));const used=orgAudits().filter(a=>monthKey(a.date)===mk).length;const members=(store.users||[]).filter(u=>u.orgId===o.id);const adm=can("manage");const ops=store.ops||{};const kb=Math.round(JSON.stringify(store.audits||[]).length/1024);let rc=`<span class="pill info">non renseignée</span>`;if(L.rcpro){const d=Math.ceil((new Date(L.rcpro)-Date.now())/864e5);rc=d<0?`<span class="pill crit">expirée depuis ${-d} j</span>`:d<60?`<span class="pill high">expire dans ${d} j</span>`:`<span class="pill okk">valide (${d} j)</span>`;}
box.innerHTML=`${stepperHTML(5)}<div class="grid g2"><div class="card"><h3>Organisation active</h3><div class="row"><input type="text" id="orgNameInput" value="${esc(o.name)}" ${adm?"":"disabled"} style="max-width:220px"><select id="orgTypeSel" ${adm?"":"disabled"} style="max-width:150px">${["PME","ETI","Agence","Public","Autre"].map(t=>`<option ${t===o.type?"selected":""}>${t}</option>`).join("")}</select><select id="orgPlanSel" ${adm?"":"disabled"} style="max-width:200px">${Object.entries(PLANS).map(([k,v])=>`<option value="${k}" ${k===o.plan?"selected":""}>${v.label} — ${v.quota}/mois</option>`).join("")}</select>${adm?`<button class="btn ghost" id="orgSaveBtn">Enregistrer</button>`:""}</div><div class="mut" style="margin-top:8px">Quota ${esc(p.label)} : <b>${used}/${p.quota}</b> audits ce mois-ci · Données cloisonnées : ${orgAudits().length} audit(s) visibles dans cette organisation.</div>${adm?`<div class="row" style="margin-top:8px"><input type="text" id="newOrgName" placeholder="Nouvelle organisation (ex. Client X)" style="max-width:220px"><select id="newOrgType" style="max-width:130px"><option>PME</option><option>ETI</option><option>Agence</option><option>Public</option><option>Autre</option></select><button class="btn ghost" id="newOrgBtn">+ Organisation</button></div>`:""}<div class="notice" style="margin-top:8px"><b>Membres (${members.length})</b><table><tr><th>Nom</th><th>Rôle</th><th></th></tr>${members.map(m=>`<tr><td>${esc(m.name)}<div class="mut" style="font-size:11px">${esc(m.email||"")}</div></td><td>${adm?`<select data-mrole="${m.id}" style="max-width:130px">${["admin","auditeur","lecteur"].map(r=>`<option ${r===m.role?"selected":""}>${r}</option>`).join("")}</select>`:`<span class="pill info">${m.role}</span>`}</td><td>${adm?`<button class="btn warn" data-rm="${m.id}">Retirer</button>`:""}</td></tr>`).join("")}</table>${adm?`<div class="row" style="margin-top:8px"><input type="text" id="memberName" placeholder="Nom" style="max-width:150px"><input type="text" id="memberEmail" placeholder="Email (optionnel)" style="max-width:200px"><select id="memberRole" style="max-width:130px"><option>admin</option><option selected>auditeur</option><option>lecteur</option></select><button class="btn" id="memberAddBtn">+ Membre</button></div><div class="mut" style="font-size:11px;margin-top:6px">Rôles : admin (tout), auditeur (audits + vérification + exports), lecteur (consultation seule). Authentification locale de démo — SSO à prévoir avant vente grand compte.</div>`:`<div class="mut">Modification réservée aux admins.</div>`}</div></div><div class="card"><h3>Juridique & conformité</h3><div class="row"><input type="text" id="legalRaison" placeholder="Raison sociale" value="${esc(L.raison||"")}" ${adm?"":"disabled"} style="max-width:200px"><input type="text" id="legalSiren" placeholder="SIREN" value="${esc(L.siren||"")}" ${adm?"":"disabled"} style="max-width:140px"><input type="text" id="legalDpo" placeholder="Email DPO" value="${esc(L.dpo||"")}" ${adm?"":"disabled"} style="max-width:200px"><input type="date" id="legalRcpro" value="${esc(L.rcpro||"")}" ${adm?"":"disabled"} title="Échéance RC pro"></div><div class="row" style="margin-top:8px">${adm?`<button class="btn ghost" id="legalSaveBtn">Enregistrer</button><button class="btn" id="cguBtn">Accepter les CGV v2026-09-30</button><button class="btn ghost" id="contractBtn">Contrat-cadre (.md)</button>`:""}</div><div class="mut" style="margin-top:8px">RC pro : ${rc} · CGV acceptées : ${((o.cgu||[]).map(g=>`${esc(g.v)} par ${esc(g.by)} le ${esc(g.date)}`).join(" · "))||"—"}</div><div class="mut" style="font-size:11px;margin-top:6px">Modèles fournis à faire valider par un avocat. Assurance RC pro cyber exigée par les grands comptes.</div></div></div><div class="grid g2" style="margin-top:12px"><div class="card"><h3>Ops & sauvegardes</h3><div class="row noPrint"><button class="btn" id="backupBtn">Sauvegarder (JSON)</button><label class="btn ghost" style="cursor:pointer">Restaurer<input type="file" id="restoreInput" accept=".json" hidden></label></div><div class="mut" style="margin-top:8px">Dernière sauvegarde : ${esc(ops.lastBackup||"jamais")} · Stockage audits : ~${kb} Ko · Hébergement : ${esc(ops.hostingNote||"à renseigner — ciblez UE pour clients européens")}</div>${adm?`<div class="row" style="margin-top:8px"><input type="text" id="hostingNote" placeholder="Ex. OVH Gravelines, UE" value="${esc(ops.hostingNote||"")}" style="max-width:260px"><button class="btn ghost" id="hostingSaveBtn">OK</button></div>`:""}<div class="notice" style="margin-top:8px"><b>Pentests tiers (${(ops.pentest||[]).length})</b>${((ops.pentest||[]).map(pt=>`<div>${esc(pt.date)} — ${esc(pt.by)} : ${esc(pt.note)}</div>`).join(""))||`<div class="mut">Aucun — planifiez un pentest annuel avant de vendre.</div>`}${adm?`<div class="row" style="margin-top:8px"><input type="text" id="pentestNote" placeholder="Ex. Pentest PASSI — rapport reçu" style="max-width:260px"><button class="btn ghost" id="pentestAddBtn">+ Entrée</button></div>`:""}</div></div><div class="card"><h3>Offres par segment</h3><table><tr><th>Plan</th><th>Quota</th><th>Cible</th></tr>${Object.entries(PLANS).map(([k,v])=>`<tr><td><b>${v.label}</b>${k===o.plan?" ●":""}</td><td>${v.quota}/mois</td><td class="mut">${k==="solo"?"TPE":k==="pme"?"PME":k==="affaires"?"ETI + SLA":"Agences multi-clients"}</td></tr>`).join("")}</table><div class="mut" style="margin-top:8px">Dépassement = blocage des nouveaux audits avec message. Facturation et SLA contractuel hors outil (cf. contrat-cadre).</div></div></div>`;
if(!adm)return;
$("#newOrgBtn").onclick=()=>{const n=$("#newOrgName").value.trim();if(!n){alert("Nom requis.");return;}const id="org-"+Math.random().toString(36).slice(2,7);store.orgs.push({id,name:n,type:$("#newOrgType").value,plan:"pme",legal:{},cgu:[],createdAt:new Date().toISOString().slice(0,10)});store.users.push({id:"u-"+Math.random().toString(36).slice(2,7),name:sessionUser().name+" (admin)",email:sessionUser().email||"",role:"admin",orgId:id});saveOrgs();switchOrg(id);};
$("#orgSaveBtn").onclick=()=>{o.name=$("#orgNameInput").value.trim()||o.name;o.type=$("#orgTypeSel").value;o.plan=$("#orgPlanSel").value;saveOrgs();refreshAll();};
$("#memberAddBtn").onclick=()=>{const n=$("#memberName").value.trim();if(!n){alert("Nom requis.");return;}store.users.push({id:"u-"+Math.random().toString(36).slice(2,7),name:n,email:$("#memberEmail").value.trim(),role:$("#memberRole").value,orgId:o.id});saveOrgs();refreshAll();};
box.querySelectorAll("[data-mrole]").forEach(s=>s.onchange=()=>{const m=store.users.find(u=>u.id===s.dataset.mrole);if(m.role==="admin"&&s.value!=="admin"&&members.filter(x=>x.role==="admin").length<=1){alert("Dernier admin : promotion d'abord.");renderOrg();return;}m.role=s.value;saveOrgs();refreshAll();});
box.querySelectorAll("[data-rm]").forEach(b=>b.onclick=()=>{const m=store.users.find(u=>u.id===b.dataset.rm);if(m.role==="admin"&&members.filter(x=>x.role==="admin").length<=1){alert("Impossible : dernier admin.");return;}store.users=store.users.filter(u=>u.id!==m.id);if(store.session.userId===m.id)store.session.userId=(store.users.find(u=>u.orgId===o.id)||{}).id;saveOrgs();refreshAll();});
$("#legalSaveBtn").onclick=()=>{o.legal={raison:$("#legalRaison").value.trim(),siren:$("#legalSiren").value.trim(),dpo:$("#legalDpo").value.trim(),rcpro:$("#legalRcpro").value};saveOrgs();renderOrg();};
$("#cguBtn").onclick=()=>{o.cgu=o.cgu||[];o.cgu.push({v:"CGV-2026-09-30",by:sessionUser().name,date:new Date().toISOString().slice(0,16).replace("T"," ")});saveOrgs();renderOrg();};
$("#contractBtn").onclick=()=>{const b=new Blob([contractText()],{type:"text/markdown"});const u=URL.createObjectURL(b);const l=document.createElement("a");l.href=u;l.download="contrat-cadre-"+o.name.replace(/\W+/g,"-")+".md";l.click();};
$("#backupBtn").onclick=()=>backupAll();
$("#restoreInput").onchange=e=>{if(e.target.files[0])restoreAll(e.target.files[0]);};
$("#hostingSaveBtn").onclick=()=>{store.ops={...(store.ops||{}),hostingNote:$("#hostingNote").value.trim()};saveOrgs();renderOrg();};
$("#pentestAddBtn").onclick=()=>{const v=$("#pentestNote").value.trim();if(!v)return;store.ops={...(store.ops||{}),pentest:[...((store.ops||{}).pentest||[]),{date:new Date().toISOString().slice(0,10),by:sessionUser().name,note:v}]};saveOrgs();renderOrg();};}
function boot(){$("#webChecks").innerHTML=WEB_CHECKS.map(([v,l])=>`<label class="chk"><input type="checkbox" value="${v}" checked> ${l}</label>`).join("");$("#codeChecks").innerHTML=CODE_CHECKS.map(([v,l])=>`<label class="chk"><input type="checkbox" value="${v}" checked> ${l}</label>`).join("");document.querySelectorAll(".nav button").forEach(b=>b.onclick=()=>show(b.dataset.view));if($("#orgSel")){$("#orgSel").onchange=e=>switchOrg(e.target.value);}if($("#userSel")){$("#userSel").onchange=e=>switchUser(e.target.value);}$("#newAuditTopBtn").onclick=()=>show("new");loadPrefs();if($("#localOnlyChk")){$("#localOnlyChk").checked=!!prefs.localOnly;$("#localOnlyChk").onchange=e=>{prefs.localOnly=e.target.checked;savePrefs();log("Mode local-only : "+(prefs.localOnly?"ACTIVÉ (aucune donnée vers l'IA externe)":"désactivé"));};}
if($("#authByInput")){$("#authByInput").value=prefs.authBy||"";$("#authByInput").oninput=e=>{prefs.authBy=e.target.value;savePrefs();};}$("#startWebBtn").onclick=runWeb;$("#startCodeBtn").onclick=runCode;$("#demoWebBtn").onclick=()=>{$("#targetInput").value="https://example.com";$("#authWebChk").checked=true;runWeb();};$("#demoCodeBtn").onclick=()=>{$("#codeInput").value='===== package.json =====\n{"name":"shop","dependencies":{"express":"4.17.1","lodash":"4.17.15","axios":"0.21.1"}}\n===== src/services/payment.ts =====\nconst apiKey = "sk_live_51H7xYZsecretkey123456789";\nfunction authenticateUser(){ const db = "mongodb://admin:Sup3rSecret@db:27017/shop"; }\napp.post("/pay",(req,res)=>{const q="SELECT * FROM users WHERE id="+req.body.id;eval(req.body.coupon);res.innerHTML=req.body.name;});\nconst h=crypto.createHash("md5");\n===== .env.example =====\nAPI_KEY=sk_live_****************\nJWT_SECRET=motdepasse123\n===== nginx.conf =====\nserver_tokens on;\n';$("#authCodeChk").checked=true;runCode();};$("#loadRepoBtn").onclick=async()=>{const u=$("#repoInput").value.trim();if(!u)return;$("#scanLog").innerHTML="";log("Chargement GitHub : "+u);try{const files=await loadGitHub(u,$("#branchInput").value.trim()||"main");$("#codeInput").value=files.map(f=>`===== ${f.name} =====\n${f.content}`).join("\n");log(files.length+" fichiers chargés.");}catch(e){log("ERREUR GitHub : "+e.message);alert(e.message);}};$("#exportJsonLink").onclick=e=>{e.preventDefault();if(store.current){const b=new Blob([JSON.stringify(store.current,null,2)],{type:"application/json"});const u=URL.createObjectURL(b);const l=document.createElement("a");l.href=u;l.download="audit.json";l.click();}};$("#printLink").onclick=e=>{e.preventDefault();printReportV2();};load().then(refreshAll);}
document.readyState!=="loading"?boot():document.addEventListener("DOMContentLoaded",boot);
